#:project /var/folders/09/c3s_t1kd4m91p7yltrx08snw0000gn/T/sv-f2fe8808a2e3482ea34291308a025fb4/Report.csproj

using Markout;
using System.Reflection;

// Find IMarkoutFormatter implementations
var asm = typeof(MarkoutSerializer).Assembly;
var formatters = asm.GetTypes()
    .Where(t => t.IsClass && !t.IsAbstract && typeof(IMarkoutFormatter).IsAssignableFrom(t))
    .ToList();

Console.WriteLine($"Found {formatters.Count} IMarkoutFormatter implementations:");
foreach (var f in formatters)
{
    Console.WriteLine($"  {f.Name}");

    // Check for static Default or Instance
    var defaultProp = f.GetProperty("Default", BindingFlags.Public | BindingFlags.Static);
    var instanceProp = f.GetProperty("Instance", BindingFlags.Public | BindingFlags.Static);

    if (defaultProp != null) Console.WriteLine($"    - has static Default");
    if (instanceProp != null) Console.WriteLine($"    - has static Instance");

    // Check constructors
    var ctors = f.GetConstructors(BindingFlags.Public);
    foreach (var ctor in ctors)
    {
        var parms = string.Join(", ", ctor.GetParameters().Select(p => p.ParameterType.Name));
        Console.WriteLine($"    - ctor({parms})");
    }
}
EOF
